"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["98300"],{19839(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>a,contentTitle:()=>r,toc:()=>h,assets:()=>l});var n=JSON.parse('{"id":"qiangguo/forumkyc","title":"","description":"These past couple of days, some people have been performing the classic ruse of \\"Zhou Yu hitting Huang Gai\\" on the forum -- some performing, some cheering them on -- making the forum a filthy mess. The forum always has a group of bored people who are not here to discuss issues. They spend all day watching click counts; they accuse everyone of being someone\'s sockpuppet while actually maintaining a pile of sockpuppets themselves; they follow certain people around all day like sycophants, going \\"great post, great post,\\" turning the forum into their personal stage show -- playing good cop and bad cop, thieves crying \\"stop thief,\\" framing and entrapping others, and putting on ghostly airs.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/forumkyc.md","sourceDirName":"qiangguo","slug":"/qiangguo/forumkyc","permalink":"/en/qiangguo/forumkyc","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"forumkyc","title":"","hide_table_of_contents":true,"sidebar_label":"From the recent farce of people staging fake quarrels on the forum \u2014 the necessity of implementing real-name registration"},"sidebar":"qiangguoSidebar","previous":{"title":"\u5B54\u57A2\u5112\u5C18\u662F\u5426\u53C8\u5230\u8BE5\u6E05\u626B\u7684\u65F6\u5019\uFF1F","permalink":"/en/qiangguo/timetocleanconfucianism"},"next":{"title":"A serious argument: Chiang Kai-shek","permalink":"/en/qiangguo/chiangkaishek"}}'),i=o(74848),s=o(28453);let a={id:"forumkyc",title:"",hide_table_of_contents:!0,sidebar_label:"From the recent farce of people staging fake quarrels on the forum \u2014 the necessity of implementing real-name registration"},r='From the Recent Farce of "Zhou Yu Hitting Huang Gai" on the Forum, On the Necessity of Implementing Real-Name Registration',l={},h=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"from-the-recent-farce-of-zhou-yu-hitting-huang-gai-on-the-forum-on-the-necessity-of-implementing-real-name-registration",children:'From the Recent Farce of "Zhou Yu Hitting Huang Gai" on the Forum, On the Necessity of Implementing Real-Name Registration'})}),"\n",(0,i.jsx)(t.p,{children:'These past couple of days, some people have been performing the classic ruse of "Zhou Yu hitting Huang Gai" on the forum -- some performing, some cheering them on -- making the forum a filthy mess. The forum always has a group of bored people who are not here to discuss issues. They spend all day watching click counts; they accuse everyone of being someone\'s sockpuppet while actually maintaining a pile of sockpuppets themselves; they follow certain people around all day like sycophants, going "great post, great post," turning the forum into their personal stage show -- playing good cop and bad cop, thieves crying "stop thief," framing and entrapping others, and putting on ghostly airs.'}),"\n",(0,i.jsx)(t.p,{children:'Having click counts displayed behind posts was already a pointless feature to begin with. One solution would be to hide click counts so nobody can see them, which would prevent the jealousy-fueled quarrels of certain people. As for so-called hot posts, the moderators can manage this based on internal click data, or simply abolish the hot post feature entirely. The forum is meant for discussing issues -- what matters is the issue itself. Besides, isn\'t truth said to be in the hands of the few? Having people constantly saying "great post, great post" in the comments might still just be foul air.'}),"\n",(0,i.jsx)(t.p,{children:"But the ultimate solution is implementing real-name registration. With real names, sockpuppets would be impossible. More importantly, it would eliminate the possibility of certain people creating disturbances by falsely accusing others of being sockpuppets. Second, with real-name registration, everyone would be more responsible for their behavior, and the cliquish behavior of singing in chorus like a theatrical troupe would be eliminated, giving the forum a fresh atmosphere. With real-name registration, those irresponsible remarks about who is receiving Japanese yen, US dollars, or rubles would become impossible -- if anyone talks nonsense, they can be taken straight to court. With real-name registration, it would further cultivate civic consciousness and showcase the achievements of free speech, shutting the Americans' foul mouths."}),"\n",(0,i.jsx)(t.p,{children:'Last week, this young lady already wrote "Real-Name Registration Is the Best Way to Solve Forum Desertification and Free-Market-ification." Here it is necessary to raise this suggestion once more. The Strong Nation Forum is a fine place for freely expressing opinions. Everyone must cherish it, but it also needs institutional improvement -- and real-name registration is what is necessary.'})]})}function c(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}},28453(e,t,o){o.d(t,{R:()=>a,x:()=>r});var n=o(96540);let i={},s=n.createContext(i);function a(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);